import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"数据与隐私","description":"","frontmatter":{},"headers":[],"relativePath":"zh/online/privacy.md","filePath":"zh/online/privacy.md","lastUpdated":1792570296000}'),n={name:"zh/online/privacy.md"};function i(l,a,s,h,c,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="数据与隐私" tabindex="-1">数据与隐私 <a class="header-anchor" href="#数据与隐私" aria-label="Permalink to &quot;数据与隐私&quot;">​</a></h1><p>在线版如何处理你的密钥、检索和历史。</p><h2 id="已保存的密钥" tabindex="-1">已保存的密钥 <a class="header-anchor" href="#已保存的密钥" aria-label="Permalink to &quot;已保存的密钥&quot;">​</a></h2><p>在设置中保存的密钥在 PaperSeek 服务器上加密存储，只用于你自己的任务，保存后不再显示，页面只显示末 4 位。可在 <strong>设置 › 用户</strong> 中删除全部已保存密钥，见<a href="./account">账户与登录</a>。</p><h2 id="不登录检索" tabindex="-1">不登录检索 <a class="header-anchor" href="#不登录检索" aria-label="Permalink to &quot;不登录检索&quot;">​</a></h2><p>没有账户也可以做一次临时检索：在检索表单中选择服务商和模型，直接填写模型密钥（数据源需要时也填写数据源密钥）。密钥只用于这次检索，不会保存，也不会写入浏览器。</p><p>临时检索保存在服务器内存中。有效期内可以刷新当前标签页，但不会进入历史；关闭标签页、过期或服务重启后可能无法再查看。文献计量、综述、历史和设置需要登录。想保留的检索请<strong>先登录再开始</strong>；之后登录不会导入临时检索。</p><h2 id="你的历史" tabindex="-1">你的历史 <a class="header-anchor" href="#你的历史" aria-label="Permalink to &quot;你的历史&quot;">​</a></h2><p>登录后的检索、分析和综述保存在账户中，可以重新打开。可在 <strong>设置 › 用户</strong> 中清空历史；清空会先停止正在运行的任务，不影响积分扣费记录。详见<a href="./account">账户与登录</a>。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="./byok">自带密钥</a> — 已保存密钥的配置和范围。</li><li><a href="./../self-hosting/">自部署</a> — 使用社区版把全部数据留在自己的设备上。</li></ul>',11)])])}const u=e(n,[["render",i]]);export{_ as __pageData,u as default};
